from typing import Any, Optional

import pydantic

from mlflow.exceptions import MlflowException
from mlflow.genai.judges.adapters import databricks_managed_judge_adapter
from mlflow.genai.judges.constants import _DATABRICKS_DEFAULT_JUDGE_MODEL
from mlflow.genai.utils.message_utils import pydantic_to_response_format

# NB: These helpers are imported here so they are patchable at
# ``mlflow.genai.scorers.llm_backend`` and shared by all scorer integrations.
