class ScorerLLMClient:
    """Unified LLM backend client that handles routing, retry logic, and dispatch.

    The constructor accepts a model URI string and determines the appropriate
    routing strategy based on the URI format and environment configuration.

    Args:
        model_uri: The model URI, e.g. ``"databricks"``, ``"gpt-oss-120b"``,
            ``"endpoints:/my-endpoint"``, ``"openai:/gpt-4"`` or
            ``"gateway:/my-endpoint"``.
    """

    def __init__(self, model_uri: str):
        self._model_uri = model_uri

        if ":/" not in model_uri:
            # A bare name (e.g. "databricks" or "gpt-oss-120b") routes to the
            # Databricks managed judge endpoint.
            self._route = "databricks"
            self._is_native = True
            self._provider = None
            self._raw_model_name = model_uri
            self._model_name = model_uri
            return

        provider, raw_model_name = _parse_model_uri(model_uri)
        self._provider = provider
        self._raw_model_name = raw_model_name
        self._model_name = f"{provider}/{raw_model_name}"

        if provider == "endpoints":
            self._route = "endpoints"
            self._is_native = True
            return

        # Use the native gateway provider infrastructure if a provider instance
        # can be constructed (i.e. the provider is supported and the required
        # credentials are available); otherwise fall back to litellm.
        try:
            _get_provider_instance(provider, raw_model_name)
        except MlflowException:
            self._route = "litellm"
            self._is_native = False
        else:
            self._route = "native"
            self._is_native = True

    @property
    def route(self) -> str:
        return self._route

    @property
    def is_native(self) -> bool:
        return self._is_native

    @property
    def model_name(self) -> str:
        return self._model_name

    @property
    def provider(self) -> Optional[str]:
        return self._provider

    @property
    def raw_model_name(self) -> str:
        return self._raw_model_name

    @property
    def model_uri(self) -> str:
        return self._model_uri

    def complete(
        self,
        messages: list[dict],
        response_format: Any = None,
        num_retries: int = 0,
        **kwargs: Any,
    ) -> str:
        """Invoke the backing LLM and return the completion text.

        Args:
            messages: Chat messages as ``[{"role": ..., "content": ...}]``.
            response_format: Either a Pydantic ``BaseModel`` class (converted to a
                JSON schema dict) or a response-format dict passed through unchanged.
            num_retries: Number of additional retries on ``MlflowException``.
            kwargs: Additional inference parameters (e.g. ``temperature``) forwarded
                to the underlying provider.
        """
        last_exc: MlflowException | None = None
        for attempt in range(num_retries + 1):
            try:
                return self._dispatch(messages, response_format, **kwargs)
            except MlflowException as e:
                last_exc = e
                if attempt >= num_retries:
                    raise
        # Unreachable: the loop either returns or re-raises, but keep this for safety.
        raise last_exc

    def complete_prompt(self, prompt: str) -> str:
        return self.complete([{"role": "user", "content": prompt}])

    def _dispatch(self, messages: list[dict], response_format: Any, **kwargs: Any) -> str:
        if self._route == "litellm":
            return self._complete_litellm(messages, response_format, **kwargs)

        if self._route == "databricks":
            system_prompt = next(
                (m["content"] for m in messages if m.get("role") == "system"), ""
            )
            user_prompt = next((m["content"] for m in messages if m.get("role") == "user"), "")
            result = databricks_managed_judge_adapter.call_chat_completions(
                user_prompt=user_prompt,
                system_prompt=system_prompt,
                model=self._model_uri,
            )
            return result.output

        # Native and endpoints routes both go through the gateway provider API.
        return _call_llm_provider_api(
            self._provider,
            self._raw_model_name,
            messages=messages,
            eval_parameters=kwargs or None,
            response_format=self._normalize_response_format(response_format),
        )

    def _complete_litellm(self, messages: list[dict], response_format: Any, **kwargs: Any) -> str:
        try:
            import litellm
        except ImportError:
            raise MlflowException(
                f"Model '{self._model_uri}' is not natively supported. To use it, install "
                "litellm with: `pip install litellm`."
            )

        completion_kwargs = dict(kwargs)
        if response_format is not None:
            completion_kwargs["response_format"] = self._normalize_response_format(response_format)

        response = litellm.completion(
            model=self._model_name,
            messages=messages,
            **completion_kwargs,
        )
        return response.choices[0].message.content

    @staticmethod
    def _normalize_response_format(response_format: Any) -> Optional[dict]:
        if response_format is None:
            return None
        if isinstance(response_format, dict):
            return response_format
        if isinstance(response_format, type) and issubclass(response_format, pydantic.BaseModel):
            return pydantic_to_response_format(response_format)
        return response_format
