def _parse_json_output_with_schema(output: str, schema):
    try:
        json_data = json.loads(output)
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to parse JSON output: {e}\nOutput: {output}")

    try:
        return schema(**json_data)
    except ValidationError as e:
        raise ValueError(f"Failed to validate output against schema: {e}\nOutput: {output}")
    except TypeError as e:
        raise ValueError(f"Failed to instantiate schema with data: {e}\nOutput: {output}")


class MlflowDeepEvalLLM(DeepEvalBaseLLM):
    """Unified DeepEval model adapter backed by a :class:`ScorerLLMClient`.

    Replaces the former ``DatabricksDeepEvalLLM`` and ``GatewayDeepEvalLLM``.
    Handles structured output via JSON prompt injection and response parsing.
    """

    def __init__(self, client: ScorerLLMClient):
        super().__init__(model_name=client.model_name)
        self._client = client

    def load_model(self, **kwargs):
        return self

    def generate(self, prompt: str, schema=None) -> str:
        # Return type is str when schema is None, or a validated schema instance when
        # schema is provided. The -> str annotation matches DeepEvalBaseLLM's abstract
        # method signature; DeepEval's own LiteLLMModel follows the same convention.
        if schema is not None:
            prompt = _build_json_prompt_with_schema(prompt, schema)

        response = self._client.complete_prompt(prompt)

        if schema is not None:
            return _parse_json_output_with_schema(response.strip(), schema)
        return response

    async def a_generate(self, prompt: str, schema=None) -> str:
        return self.generate(prompt, schema=schema)

    def get_model_name(self) -> str:
        return self._client.model_name


def create_deepeval_model(model_uri: str):
    """Create a DeepEval model adapter from a model URI.

    Returns a :class:`MlflowDeepEvalLLM` for natively-supported backends
    (databricks, endpoints, and supported providers with required API keys, plus
    gateway URIs) and falls back to litellm for unsupported providers.
    """
    client = ScorerLLMClient(model_uri)

    if client.is_native:
        return MlflowDeepEvalLLM(client)

    from deepeval.models import LiteLLMModel

    return LiteLLMModel(
        model=client.model_name,
        generation_kwargs={"drop_params": True},
    )
